from chemlib import *
c=cell
GL='chem11-glossary-index'
def pg(n,title,ur,ps,sid): return page(n,GL,title,ur,ps,sid)
def gl(s,rows,cap,cu,cp):
    s['tables']=[table(cap,cu,cp,[c('Term','اصطلاح','اصطلاح'),c('Definition','تعریف','تعریف')],[[c(*t),c(*d)] for t,d in rows])]
    s['vocabulary']={w:dict(ur=a[1],ps=a[2]) for w,a in [(k[0][0].lower(),k[0]) for k in rows] if w.isascii() and w.replace(' ','').isalpha()}
    s['vocabulary']['glossary']=dict(ur='فرہنگ',ps='وييپانګه')
    s['paras']=[]
    add(s,'h','GLOSSARY','فرہنگ','وييپانګه',kind='heading')
    s['flow']=[dict(type='paragraphs',ids=[f"chem11-p{s['source']['pdfPage']}-h"]),dict(type='table',index=0)]
def Rw(a,b,c_,d,e,f): return ((a,b,c_),(d,e,f))

