R=[
Rw('Lattice energy','جالی توانائی','د جالۍ انرژي','The energy that is given off as an ionic crystal forms from the gaseous ions of its elements','وہ توانائی جو آئنی قلم کے اس کے عناصر کے گیسی آئنوں سے بننے پر خارج ہوتی ہے','هغه انرژي چې کله یو آیوني کرسټال د خپلو عناصرو له ګازي آیونونو څخه جوړېږي خوشې کېږي'),
Rw('Lattice energy','جالی توانائی','د جالۍ انرژي','It is the amount of energy released when gaseous ions of opposite charges combine to give one mole of a crystal lattice.','یہ توانائی کی وہ مقدار ہے جو مخالف چارجوں کے گیسی آئنوں کے ملنے سے قلمی جالی کا ایک مول بننے پر خارج ہوتی ہے۔','دا د انرژي هغه مقدار دی چې کله د مخالفو چارجونو ګازي آیونونه یوځای شي ترڅو د کرسټالي جالۍ یو مول جوړ کړي خوشې کېږي.'),
Rw('Law of conservation of mass (matter)','کمیت (مادے) کی بقا کا قانون','د کتلې (ماده) د ساتنې قانون','Law of conservation of mass (matter), which states that matter (mass) can neither be created nor destroyed','کمیت (مادے) کی بقا کا قانون، جو بیان کرتا ہے کہ مادہ (کمیت) نہ تخلیق کیا جا سکتا ہے نہ تباہ کیا جا سکتا ہے','د کتلې (ماده) د ساتنې قانون، چې وايي ماده (کتله) نه جوړېدای شي او نه ویجاړېدای شي'),
Rw('Leveling effect','ہمواری کا اثر','هواروونکی اغېز','Strong acids are completely ionized in solution so all the strong acids have very close pKa values or they are leveled to the same extent. This phenomenon is called Leveling effect.','مضبوط تیزاب محلول میں مکمل طور پر آئنائز ہوتے ہیں اس لیے تمام مضبوط تیزابوں کی pKa قیمتیں بہت قریب ہوتی ہیں یا وہ ایک ہی حد تک ہموار ہو جاتے ہیں۔ اس مظہر کو ہمواری کا اثر کہتے ہیں۔','قوي اسیدونه په محلول کې بشپړ آیونایز کېږي نو ټول قوي اسیدونه د pKa ډېر نژدې ارزښتونه لري یا په یو ډول کچه همواره کېږي. دې پدیدې ته هواروونکی اغېز ویل کېږي.'),
Rw('Lewis acid','لیوس تیزاب','لویس اسید','An acid is an electron pair accepter.','تیزاب الیکٹران جوڑا قبول کرنے والا ہے۔','اسید د الکترون جوړه منونکی دی.'),
Rw('Lewis base','لیوس اساس','لویس اساس','A base is an electron pair donor','اساس الیکٹران جوڑا دینے والا ہے','اساس د الکترون جوړه ورکوونکی دی'),
Rw('Lewis structure','لیوس ساخت','لویس جوړښت','a structural formula in which electrons are represented by dots; dot pairs or dashes between two atomic symbols represent pairs in covalent bonds.','ایک ساختی فارمولا جس میں الیکٹرانوں کو نقطوں سے ظاہر کیا جاتا ہے؛ دو ایٹمی علامتوں کے درمیان نقطہ جوڑے یا خطوط ہم گرفتی بانڈوں میں جوڑوں کو ظاہر کرتے ہیں۔','یوه جوړښتي فورمول چې په هغه کې الکترونونه په ټکو ښودل کېږي؛ د دوو اتومي سمبولونو ترمنځ د ټکو جوړې یا کرښې په همولانسیک بانډونو کې جوړې ښيي.'),
Rw('Limiting Reagent','محدود کرنے والا متعامل','محدودوونکی تعامل کوونکی','The reactant that is consumed quickly and completely during a chemical reaction, or, which produces the least number of moles of products in a chemical reaction.','وہ متعامل جو کیمیائی تعامل کے دوران تیزی سے اور مکمل طور پر صرف ہو جائے، یا جو کیمیائی تعامل میں حاصلات کے مولوں کی سب سے کم تعداد پیدا کرے۔','هغه تعامل کوونکی چې د کیمیاوي تعامل پر مهال ژر او بشپړ مصرف شي، یا چې په کیمیاوي تعامل کې د محصولاتو د مولونو تر ټولو لږ شمېر تولید کړي.'),
Rw('Liquefaction of Gases','گیسوں کا مائع بننا','د ګازونو مایع کېدل','The process in which the gases are converted to its liquid state by lowering temperature and increasing pressure is called liquefaction of gases.','وہ عمل جس میں درجہ حرارت گھٹا کر اور دباؤ بڑھا کر گیسوں کو مائع حالت میں بدلا جاتا ہے گیسوں کا مائع بننا کہلاتا ہے۔','هغه بهیر چې په هغه کې د تودوخې په کمولو او فشار په زیاتولو سره ګازونه مایع حالت ته بدلېږي د ګازونو مایع کېدل بلل کېږي.'),
Rw('London dispersion forces','لندن منتشری قوتیں','لندن د خپرېدو ځواکونه','The attractive forces between the temporary dipoles of one molecule are called London dispersion forces.','ایک مالیکیول کے عارضی ڈائی پولوں کے درمیان کششی قوتیں لندن منتشری قوتیں کہلاتی ہیں۔','د یو مالیکول د لنډمهاله ډای پولونو ترمنځ جذبي ځواکونه لندن د خپرېدو ځواکونه بلل کېږي.'),
Rw('Magnetic Quantum Number','مقناطیسی کوانٹم عدد','مقناطیسي کوانټم شمېره','This quantum number has been based upon the splitting up of spectral lines (Zeeman Effect). This quantum number is also called Orientation Quantum Number because this quantum number indicates the orientation of the orbital in the space around the nucleus.','یہ کوانٹم عدد طیفی لکیروں کے ٹوٹنے (زیمان اثر) پر مبنی ہے۔ اس کوانٹم عدد کو سمتی کوانٹم عدد بھی کہتے ہیں کیونکہ یہ کوانٹم عدد مرکزے کے گرد خلا میں مدار کی سمت بندی ظاہر کرتا ہے۔','دا کوانټم شمېره د سپېکټري کرښو په ویشلو (زیمان اغېز) والړه ده. دې کوانټم شمېرې ته د لوري کوانټم شمېره هم ویل کېږي ځکه چې دا کوانټم شمېره د هستې شاوخوا په ځای کې د اوربیټل لوری ښيي.'),
Rw('Malleable','کوٹنے کے قابل','لوټېدونکی','A property of metals; can be rolled or hammered into sheets.','دھاتوں کی ایک خاصیت؛ انہیں چادروں میں بیلا یا کوٹا جا سکتا ہے۔','د فلزاتو یوه ځانګړتیا؛ دوی په ورقو کې رالوېدای یا کوټل کېدای شي.'),
Rw('Metallic bond','دھاتی بانڈ','فلزي بانډ',"An electrostatic force of attraction between the mobile 'sea' of electrons and the regular array of positive metal ions within a solid metal.",'ٹھوس دھات کے اندر الیکٹرانوں کے متحرک "سمندر" اور مثبت دھاتی آئنوں کی باقاعدہ صف کے درمیان برق سکونی کششی قوت۔','په جامد فلز کې د الکترونونو د خوځنده "سمندر" او د مثبتو فلزي آیونونو د منظمې لړۍ ترمنځ د برېښنا ساکن جذب ځواک.'),
Rw('Metalloids','نیم دھاتیں','نیمه فلزات','(Semi-metal) any of the class of chemical elements intermediate in properties between metals and non-metals, for example, boron and silicon','(نیم دھات) کیمیائی عناصر کی اس جماعت میں سے کوئی بھی جو خصوصیات میں دھاتوں اور غیر دھاتوں کے درمیان ہو، مثلاً بورون اور سلیکون','(نیمه فلز) د کیمیاوي عناصرو د هغې ډلې هر یو چې په ځانګړتیاوو کې د فلزاتو او غیر فلزاتو ترمنځ وي، د بېلګې په توګه بورون او سیلیکون'),
Rw('Miscible','قابلِ آمیزش','مخلوطېدونکی','Capable of mixing and forming a solution','ملنے اور محلول بنانے کے قابل','د ګډېدو او محلول جوړولو وړ')]
